<script>
const blue=[65,8,90,81,56,55,40], green=[21,48,40,19,96,27,99];
const xs=[48,149,250,351,452,553,653], base=306, scale=1.98;
function smooth(points){
  let d=`M ${points[0][0]} ${points[0][1]}`;
  for(let i=0;i<points.length-1;i++){
    const p=points[i], n=points[i+1], mx=(p[0]+n[0])/2;
    d+=` C ${mx} ${p[1]}, ${mx} ${n[1]}, ${n[0]} ${n[1]}`;
  }
  return d;
}
function draw(){
  const make=(arr)=>arr.map((v,i)=>[xs[i],base-v*scale]);
  const bp=make(blue),gp=make(green);
  document.getElementById('blueFill').setAttribute('d',smooth(bp)+` L 653 ${base} L 48 ${base} Z`);
  document.getElementById('greenFill').setAttribute('d',smooth(gp)+` L 653 ${base} L 48 ${base} Z`);
  let html='';
  bp.forEach((p,i)=>html+=`<text x="${p[0]}" y="${p[1]-8}">${blue[i]}</text>`);
  gp.forEach((p,i)=>html+=`<text x="${p[0]}" y="${p[1]-8}">${green[i]}</text>`);
  document.getElementById('labels').innerHTML=html;
}
draw();
document.querySelectorAll('.editable').forEach(cell=>{
  cell.addEventListener('input',()=>{
    const val=parseFloat(cell.innerText.trim());
    if(!isNaN(val)){
      const arr=cell.dataset.series==='blue'?blue:green;
      arr[+cell.dataset.index]=Math.max(0,Math.min(100,val));
      draw();
    }
  });
  cell.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();cell.blur()}});
});
document.getElementById('pointBtn').addEventListener('click',()=>{
  const p=document.getElementById('pointSettings');
  p.style.display=p.style.display==='none'?'block':'none';
});
document.querySelectorAll('.section').forEach(el=>{
  if(el.id!=='pointBtn') el.addEventListener('click',()=>el.classList.toggle('open'));
});
</script>
